def solution(input_str):
    input_str = input_str.strip()
    if not input_str:
        return "1\n"

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    offers = []
    for i in range(1, m + 1):
        l, r = map(int, lines[i].split())
        offers.append((l, r))

    result = []
    for x in range(1, n + 1):
        occupied = set()
        days_occupied = 0
        for l, r in offers:
            duration = r - l + 1
            if duration >= x:
                # Check if all days from l to r are empty
                can_accept = True
                for day in range(l, r + 1):
                    if day in occupied:
                        can_accept = False
                        break
                if can_accept:
                    for day in range(l, r + 1):
                        days_occupied += 1
        result.append(str(days_occupied))

    return "\n".join(result) + "\n"
