def solution(args):
    # Parse input
    data = args.split()
    n = int(data[0])
    k = int(data[1])
    a = [int(x) for x in data[2:]]

    # Memoization for Grundy value computation
    memo = {}

    def grundy(x):
        if x == 0:
            return 0
        if x in memo:
            return memo[x]

        mex = set()

        # Option 1: Remove 1 cow
        mex.add(grundy(x - 1))

        # Option 2: If x is even, split into k piles of size x//2
        if x % 2 == 0:
            x_half = x // 2
            if k % 2 == 1:
                # k is odd: XORing odd copies of g(x_half) = g(x_half)
                mex.add(grundy(x_half))
            else:
                # k is even: XORing even copies of g(x_half) = 0
                mex.add(0)

        # Find mex (minimum excluded value)
        for i in range(100):  # Upper bound reasonable for game
            if i not in mex:
                result = i
                break

        memo[x] = result
        return result

    # XOR sum of all pile Grundy values
    xor_sum = 0
    for x in a:
        xor_sum ^= grundy(x)

    # Determine winner
    if xor_sum != 0:
        return "Kevin"
    else:
        return "Nicky"
