def solution(input_str):
    import sys
    from collections import deque

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    edges = []
    for line in lines[3:3+m]:
        u, v = map(int, line.split())
        edges.append((u, v))

    # Source = 0, Cities = 1..n, Sink = n+1
    S = 0
    T = n + 1
    capacity = [[0] * (n + 2) for _ in range(n + 2)]

    # Source to each city with capacity equal to initial army size
    for i in range(1, n + 1):
        capacity[S][i] = a[i-1]

    # Each city to sink with capacity equal to target army size
    for i in range(1, n + 1):
        capacity[i][T] = b[i-1]

    # Cities to each other (including self) - infinite capacity if connected
    for i in range(1, n + 1):
        capacity[i][i] = 1000000  # large enough capacity
        for u, v in edges:
            capacity[u][v] = 1000000
            capacity[v][u] = 1000000

    # Adjacency list
    adj = [[] for _ in range(n + 2)]
    for i in range(n + 2):
        for j in range(n + 2):
            if capacity[i][j] > 0:
                adj[i].append(j)

    # Dinic's algorithm implementation
    level = [0] * (n + 2)
    ptr = [0] * (n + 2)

    def bfs():
        for i in range(n + 2):
            level[i] = -1
        level[S] = 0
        queue = deque([S])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if capacity[u][v] > 0 and level[v] == -1:
                    level[v] = level[u] + 1
                    queue.append(v)
        return level[T] != -1

    def dfs(u, pushed):
        if pushed == 0 or u == T:
            return pushed
        for i in range(ptr[u], len(adj[u])):
            ptr[u] = i
            v = adj[u][i]
            if level[v] == level[u] + 1 and capacity[u][v] > 0:
                tr = dfs(v, min(pushed, capacity[u][v]))
                if tr == 0:
                    continue
                capacity[u][v] -= tr
                capacity[v][u] += tr
                return tr
        return 0

    max_flow = 0
    while bfs():
        ptr = [0] * (n + 2)
        while True:
            pushed = dfs(S, float('inf'))
            if pushed == 0:
                break
            max_flow += pushed

    total_initial = sum(a)

    if max_flow != total_initial:
        return "NO\n"

    # Reconstruct flow matrix showing soldiers moving from each city to each
