def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    adj = [[] for _ in range(n + 1)]
    for line in lines[3:3+m]:
        u, v = map(int, line.split())
        adj[u].append(v)
        adj[v].append(u)

    S, T = 0, n + 1
    cap = [[0] * (n + 2) for _ in range(n + 2)]

    for i in range(1, n + 1):
        cap[S][i] = a[i-1]
        cap[i][T] = b[i-1]
        cap[i][i] = 1000000

    for u in range(1, n + 1):
        for v in adj[u]:
            cap[u][v] = 1000000

    adj_list = [[] for _ in range(n + 2)]
    for i in range(n + 2):
        for j in range(n + 2):
            if cap[i][j] > 0:
                adj_list[i].append(j)

    level = [0] * (n + 2)
    ptr = [0] * (n + 2)

    def bfs():
        for i in range(n + 2):
            level[i] = -1
        level[S] = 0
        q = deque([S])
        while q:
            u = q.popleft()
            for v in adj_list[u]:
                if cap[u][v] > 0 and level[v] < 0:
                    level[v] = level[u] + 1
                    q.append(v)
        return level[T] >= 0

    def dfs(u, f):
        if f == 0 or u == T:
            return f
        for i in range(ptr[u], len(adj_list[u])):
            ptr[u] = i
            v = adj_list[u][i]
            if level[v] == level[u] + 1 and cap[u][v] > 0:
                d = dfs(v, min(f, cap[u][v]))
                if d > 0:
                    cap[u][v] -= d
                    cap[v][u] += d
                    return d
        return 0

    flow = 0
    while bfs():
        ptr = [0] * (n + 2)
        while True:
            d = dfs(S, float('inf'))
            if d == 0:
                break
            flow += d

    return "NO\n" if flow != sum(a) else "YES\n" + "\n".join([str(0) for _ in range(n)])
