```python
from math import gcd

def find_divisors(n):
    divisors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i * i != n:
                divisors.append(n // i)
    divisors.sort()
    return divisors

def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            count = 0
            while temp % d == 0:
                count += 1
                temp //= d
            factors[d] = count
        d += 1
    if temp > 1:
        factors[temp] = 1
    return factors

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""
    t = int(lines[0])

    result = []
    idx = 1

    for _ in range(t):
        if idx >= len(lines):
            break
        n = int(lines[idx])
        idx += 1

        divisors = find_divisors(n)
        factorization = get_prime_factorization(n)

        num_distinct = len(factorization)
        is_square_free = all(exp == 1 for exp in factorization.values())

        if num_distinct == 1:
            moves = 0
        elif num_distinct == 2:
            if is_square_free:
                moves = 1
            else:
                moves = 0
        else:
            moves = 0

        result.append(" ".join(map(str, divisors)))
        result.append(str(moves))

    return "\n".join(result)
