def combination_mod(n, k, mod):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    # Compute C(n, k) % mod
    num = 1
    den = 1

    for i in range(k):
        num = (num * (n - i)) % mod
        den = (den * (i + 1)) % mod

