        a = list(map(int, lines[1].split()))
        e = list(map(int, lines[2].split()))

        if len(a) != n or len(e) != n:
            return "-1\n"

        # Calculate initial GCD
        current_gcd = a[0]
        for i in range(1, len(a)):
            current_gcd = gcd(current_gcd, a[i])

        # If GCD is already 1, cost is 0
        if current_gcd == 1:
            return "0\n"

        # Factorize GCD to get prime factors
        prime_factors = set()
        temp = current_gcd
        d = 2
        while d * d <= temp:
            while temp % d == 0:
                prime_factors.add(d)
                temp //= d
            d += 1
        if temp > 1:
            prime_factors.add(temp)

        # For each prime factor, find minimum experience
        min_exp_per_prime = []
        for p in prime_factors:
            if p > k:
                return "-1\n"

            min_e = float('inf')
            for i in range(n):
                if a[i] % p == 0:
                    min_e = min(min_e, e[i])

            if min_e == float('inf'):
                return "-1\n"

            min_exp_per_prime.append((p, min_e))

        # Greedily select unique judges with minimum experience
        visited = set()
        total_exp = 0
        num_judges = 0

        for p, min_e in min_exp_per_prime:
            selected_judge = -1
            for i in range(n):
                if i not in visited and a[i] % p == 0 and e[i] == min_e:
                    selected_judge = i
                    visited.add(i)
                    break

            if selected_judge != -1:
                num_judges += 1
                total_exp += e[selected_judge]
            else:
                return "-1\n"

        return f"{num_judges * total_exp}\n"

    except Exception:
        return "-1\n"
