def build_kmp_automaton(virus):
    v_len = len(virus)
    if v_len == 0:
        return [], [[0]*26 for _ in range(1)]

    pi = [0] * v_len
    for i in range(1, v_len):
        j = pi[i-1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    next_state = [[0] * 26 for _ in range(v_len + 1)]
    for state in range(v_len + 1):
        for c in range(26):
            char = chr(ord('A') + c)
            if state < v_len and char == virus[state]:
                next_state[state][ord(char) - ord('A')] = state + 1
            else:
                temp = state
                while temp > 0 and (temp == v_len or char != virus[temp]):
                    temp = pi[temp - 1]
                if temp < v_len and char == virus[temp]:
                    next_state[state][ord(char) - ord('A')] = temp + 1
                else:
                    next_state[state][ord(char) - ord('A')] = 0

    return pi, next_state


def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 3:
        return "0"

    s1 = lines[0].strip()
    s2 = lines[1].strip()
    virus = lines[2].strip()

    n, m, v_len = len(s1), len(s2), len(virus)

    pi, next_state = build_kmp_automaton(virus)

    INF = float('inf')
    dp = [[[INF] * (v_len + 1) for _ in range(n + 1)] for _ in range(m + 1)]
    parent = [[[None] * (v_len + 1) for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(v_len + 1):
                if i == 0 and j == 0:
                    dp[i][j][k] = 0
                    continue

                best_val = dp[i][j][k]
                best_par = parent[i][j][k]

                if i > 0 and dp[i-1][j][k] < best_val:
                    best_val = dp[i-1][j][k]
                    best_par = (i-1, j, k)

                if j > 0 and dp[i][j-1][k] < best_val:
                    best_val = dp[i][j-1][k]
                    best_par = (i, j-1, k)

                if i > 0 and j > 0 and s1[i-1] == s2[j-1]:
                    nk = next_state[k][ord(s1[i-1]) - ord('A')]
                    if nk < v_len and dp[i-1][j-1][k] < best_val - 1:
                        best_val = dp[i-1][j-1][k] + 1
                        best_par = (i-1, j-1, k)

                dp[i][j][k] = best_val
                parent[i][j][k] = best_par

    best_len = -1
    best_k = -1
    for k in range(v_len + 1):
        if dp[n][m][k] > best_len:
            best_len = dp[n][m][k]
            best_k = k

    if best_len < 0:
        return "0"

    res = []
    i, j, k = n, m, best_k
    while i > 0 or j > 0:
        if i == 0:
            char_c = ord(s2[j-1]) - ord('A')
            k = next_state[k][char_c]
            j -= 1
        elif j == 0:
            char_c = ord(s1[i-1]) - ord('A')
            k = next_state[k][char_c]
            i -= 1
        else:
            before_i, before_j, before_k = parent[i][j][k]
            if before_i == i-1 and before_j == j-1 and s1[i-1] == s2[j-1]:
                res.append(s1[i-1])
