    # Define helper functions
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    def order_mod(a, p):
        """Compute multiplicative order of a mod prime p"""
        if a % p == 0:
            return -1
        if p == 2:
            return 1 if a % p == 1 else -1

        if pow(a, p - 1, p) != 1:
            return -1

        phi = p - 1
        prime_divs = set()
        temp = phi
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                prime_divs.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            prime_divs.add(temp)

        order = phi
        for q in prime_divs:
            while order % q == 0:
                if pow(a, order // q, p) == 1:
                    order //= q
                else:
                    break
        return order

    def is_primitive_root(a, p):
        """Check if a is a primitive root mod prime p"""
        if not is_prime(p):
            return False
        if a % p == 0:
            return False
        if p == 2:
            return a == 1
        return order_mod(a, p) == p - 1

    def has_rotatable(n, b):
        """Check if rotatable number of length n exists in base b"""
        if n == 1:
            return True

        if is_prime(n):
            return is_primitive_root(b % n, n)
        else:
            return (b - 1) % n == 0

    # Find largest valid b
    for b in range(x - 1, 1, -1):
        if has_rotatable(n, b):
            return f"{b}\n"

    return "-1\n"


