                edge_key = (min(u, v), max(u, v))
                if edge_key in blocked_edges:
                    continue
                if len(current_path) > 1 and v in current_path:
                    continue

                blocked_edges.add(edge_key)
                current_path.append(v)
                dfs(v, target, current_path, blocked_edges, depth + 1)
                current_path.pop()
                blocked_edges.remove(edge_key)

        if len(paths) >= 3:
            return

    dfs(s, t, [s], set(), 0)
    return paths[:3]
